#include <windows.h>
#include <stdio.h>
#include "isolated_process.h"
#define CHECK(x) do{if(!(x)){fprintf(stderr,"MDI_FIX_FAIL line=%d error=%lu %s\n",__LINE__,GetLastError(),#x);return 1;}}while(0)
static int worker(int argc,WCHAR**argv){CHECK(argc==2);HMODULE f=LoadLibraryW(argv[1]);CHECK(f);BOOL (__cdecl *reg)(void)=(void*)GetProcAddress(f,"reg"),(__cdecl *unreg)(void)=(void*)GetProcAddress(f,"unreg");HWND (__cdecl *host)(void)=(void*)GetProcAddress(f,"host"),(__cdecl *child)(HWND)=(void*)GetProcAddress(f,"child");HMODULE d=GetModuleHandleW(sizeof(void*)==8?L"ntw16s64.dll":L"ntw16s32.dll");BOOL (__cdecl *attached)(HWND)=d?(void*)GetProcAddress(d,"Ntw16sWindowAttached"):NULL;CHECK(reg&&unreg&&host&&child&&attached&&reg());HWND h=host();CHECK(h);CLIENTCREATESTRUCT c={.idFirstChild=100};HWND cl=CreateWindowW(L"MDICLIENT",NULL,WS_CHILD|WS_VISIBLE,0,0,500,300,h,(HMENU)1,GetModuleHandleW(NULL),&c);CHECK(cl);HWND w=child(cl);CHECK(w);ShowWindow(h,SW_SHOWNA);UpdateWindow(h);printf("FIXTURE initial=%d root=%d\n",attached(w),attached(h));CHECK(attached(w)); HWND badhost=CreateWindowW(L"STATIC",L"bad",WS_OVERLAPPEDWINDOW,0,0,300,200,NULL,NULL,GetModuleHandleW(NULL),NULL); CHECK(badhost); HWND badclient=CreateWindowW(L"MDICLIENT",NULL,WS_CHILD|WS_VISIBLE,0,0,200,150,badhost,(HMENU)1,GetModuleHandleW(NULL),&c); CHECK(badclient); HWND bad=child(badclient); CHECK(bad); printf("FIXTURE bad_host=%d\n",attached(bad)); CHECK(!attached(bad)); CHECK(DestroyWindow(badhost));SendMessageW(cl,WM_MDIMAXIMIZE,(WPARAM)w,0);CHECK(IsZoomed(w));SendMessageW(cl,WM_MDIRESTORE,(WPARAM)w,0);CHECK(!IsZoomed(w));HWND other=CreateWindowW(L"STATIC",L"",WS_CHILD|WS_VISIBLE,0,0,200,200,h,NULL,GetModuleHandleW(NULL),NULL);CHECK(other);CHECK(SetParent(w,other)==cl);SendMessageW(w,WM_NULL,0,0);printf("FIXTURE after_reparent=%d\n",attached(w));CHECK(!attached(w));DestroyWindow(w); HWND role=child(cl);CHECK(role && attached(role)); SetWindowLongPtrW(role,GWL_EXSTYLE,GetWindowLongPtrW(role,GWL_EXSTYLE)&~WS_EX_MDICHILD); SendMessageW(role,WM_NULL,0,0); printf("FIXTURE after_role_change=%d\n",attached(role)); CHECK(!attached(role)); DestroyWindow(role); HWND w2=child(cl);CHECK(w2 && attached(w2)); BOOL (__cdecl *remove)(HWND)=(void*)GetProcAddress(d,"Ntw16sWindowRemove"); CHECK(remove&&remove(h)); SendMessageW(w2,WM_NULL,0,0); printf("FIXTURE after_host_remove=%d\n",attached(w2)); CHECK(!attached(w2)); DestroyWindow(h);CHECK(unreg());FreeLibrary(f);puts("MDI_FIX_OK");return 0;}

int wmain(int argc,WCHAR **argv){return isolated_process(argc,argv,worker);}


